{
  "headline": "FDA's records trace our supply to a plant classified OAI 198 days before the shortage posting",
  "headline_cites": ["D10"],
  "sentences": [
    {
      "text": "FDA first posted the fentanyl citrate injection shortage on 2012-01-01 and it remains current as of 2026-10-21.",
      "cites": ["E32", "E17"]
    },
    {
      "text": "The shortage lists Hospira, Inc. (NDC 0409-9094-22) and Hikma Pharmaceuticals USA, Inc. (NDC 0641-6248-10) as affected manufacturers.",
      "cites": ["E31", "E30"]
    },
    {
      "text": "Corvale East and Corvale General both stock Hospira-labeled fentanyl citrate (NDC 00409909422) per their item records.",
      "cites": ["E1", "E5"]
    },
    {
      "text": "Hospira's registered plant (FEI 1021343) received an OAI classification on 2011-06-17, 198 days before the shortage posting.",
      "cites": ["D10", "E12"]
    },
    {
      "text": "The same plant received additional OAI classifications on 2010-01-19 (712 days before posting) and 2011-08-04 (150 days before posting).",
      "cites": ["D6", "D11", "E10", "E14"]
    },
    {
      "text": "A Warning Letter was issued to this plant on 2010-04-12, 629 days before the shortage posting.",
      "cites": ["D7", "E19"]
    },
    {
      "text": "Corvale General also stocks Hikma-labeled product (NDC 00641624810) from a plant (FEI 2220525) with only VAI classifications in FDA's record.",
      "cites": ["E4", "E21", "E22", "E23", "E24", "E25", "E26", "E27"]
    }
  ]
}
